import{_ as a,c as s,o as t,aN as o}from"./chunks/framework.DXgs1r1w.js";const p="/Li6Daily/assets/img_1.aI9wzbAD.png",n="/Li6Daily/assets/img_2.CvjhUlPo.png",e="/Li6Daily/assets/img_3.PRbwiJDg.png",l="/Li6Daily/assets/img_4.RukkvsUC.png",r="/Li6Daily/assets/img_5.B32cywuq.png",d="/Li6Daily/assets/img_6.0lZ5fZBL.png",c="/Li6Daily/assets/img_7.BBx4ut5w.png",_="/Li6Daily/assets/img_8.tCtJk573.png",m="/Li6Daily/assets/img_9.CmufGlX0.png",w="/Li6Daily/assets/img_10.DQp8uJuP.png",g="/Li6Daily/assets/img_11.BP5RzYc-.png",b=JSON.parse('{"title":"Windows10 搭建 FTP 服务器（IIS）","description":"","frontmatter":{"date":"2026-08-04T10:00:00.000Z","title":"Windows10 搭建 FTP 服务器（IIS）","permalink":"/pages/f1a2b3","categories":["Protocol","文件传输协议"]},"headers":[],"relativePath":"Protocol/01.文件传输协议/03.windows10-ftp-iis.md","filePath":"Protocol/01.文件传输协议/03.windows10-ftp-iis.md","lastUpdated":1785828778000}'),P={name:"Protocol/01.文件传输协议/03.windows10-ftp-iis.md"};function f(I,i,h,u,y,T){return t(),s("div",null,[...i[0]||(i[0]=[o('<h1 id="windows10-搭建-ftp-服务器-iis" tabindex="-1">Windows10 搭建 FTP 服务器（IIS） <a class="header-anchor" href="#windows10-搭建-ftp-服务器-iis" aria-label="Permalink to &quot;Windows10 搭建 FTP 服务器（IIS）&quot;">​</a></h1><blockquote><p>本文根据原始教程文档转写，按原教程顺序保留文字与截图，未做发散。</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>FTP 协议服务端搭建的方式包含 IIS, FileZilla等 下述方式仅为Windows10 版本IIS方式。如果已存在搭建好的服务端，可根据现场环境修改FTP协议服务端网络IP，请直接跳转到标题1.3修改IP即可。</p><h2 id="创建用户" tabindex="-1">创建用户 <a class="header-anchor" href="#创建用户" aria-label="Permalink to &quot;创建用户&quot;">​</a></h2><p>创建一个用户账号用于客户端登录，假设用户名称为ftpuser</p><p>右键点击开始图标，选择计算机管理。</p><p>点击本地用户和组，选择用户。</p><p>右键点击用户，选择新用户</p><p><img src="'+p+'" alt="03.windows10-ftp-iis 截图 1" loading="lazy"></p><p>输入用户信息，下方勾选栏选项如图配置，点击创建</p><p>Tips：对于家庭版用户可能没有该功能，需要通过其他方式添加用户，参考标题1.4内容</p><p><img src="'+n+'" alt="03.windows10-ftp-iis 截图 2" loading="lazy"></p><h2 id="搭建-ftp" tabindex="-1">搭建 FTP <a class="header-anchor" href="#搭建-ftp" aria-label="Permalink to &quot;搭建 FTP&quot;">​</a></h2><p>创建完毕后，在系统左下角点击搜索栏或者通过快捷键Win+S打开搜索栏，搜索关键字“IIS管理器”，根据提示打开Internet Information Services(IIS)管理器。</p><p>进入IIS管理器后，依次点击点开左侧视图列表，随后右键单击“网站“，选择添加FTP站点。</p><p><img src="'+e+'" alt="03.windows10-ftp-iis 截图 3" loading="lazy"></p><p>输入必要信息，站点名称和物理路径，点击下一步。</p><p>Tips: 站点名称作为名称标识，可以随意修改，物理路径作为FTP服务端的根目录，即登录后的目录。假设配置得物理路径为D:\\ftp, 其下有子目录D:\\ftp\\test, 客户端使用时输入/test即可。</p><p><img src="'+l+'" alt="03.windows10-ftp-iis 截图 4" loading="lazy"></p><p>进行绑定IP、端口设置，IP地址选择本机IP，端口默认21，不启用虚拟主机名，关闭SSL证书，开启自动启动FTP站点，点击下一步。</p><p><img src="'+r+'" alt="03.windows10-ftp-iis 截图 5" loading="lazy"></p><p>进行身份验证配置，开启基本身份验证，关闭匿名登录，授权给指定用户访问，下方输入对应步骤1中的用户名，权限配置为允许读取和写入，点击完成。</p><p><img src="'+d+'" alt="03.windows10-ftp-iis 截图 6" loading="lazy"></p><h2 id="已存在服务端-修改网络-ip" tabindex="-1">已存在服务端，修改网络 IP <a class="header-anchor" href="#已存在服务端-修改网络-ip" aria-label="Permalink to &quot;已存在服务端，修改网络 IP&quot;">​</a></h2><p>对于已存在服务端，根据现场网络环境修改IP即可，可通过以下步骤实现</p><p>打开“IIS管理器”，找到已存在的FTP站点，右键单击，选择编辑绑定</p><p><img src="'+c+'" alt="03.windows10-ftp-iis 截图 7" loading="lazy"></p><p>在弹出的对话框中，双击IP地址，修改为对应的IP即可，点击确定进行保存。</p><p><img src="'+_+'" alt="03.windows10-ftp-iis 截图 8" loading="lazy"></p><p>修改IP完毕后需要对FTP站点进行重启，右键单击站点，选择管理FTP站点-重新启动。</p><h2 id="家庭版系统添加用户" tabindex="-1">家庭版系统添加用户 <a class="header-anchor" href="#家庭版系统添加用户" aria-label="Permalink to &quot;家庭版系统添加用户&quot;">​</a></h2><p>可通过命令工具打开创建菜单。按 Win+R 输入 netplwiz → 点击「添加」→ 选择「不使用 Microsoft 账户登录」→ 选择「本地账户」→输入用户名和密码完成本地账户创建。</p><p><img src="'+m+'" alt="03.windows10-ftp-iis 截图 9" loading="lazy"></p><p><img src="'+w+'" alt="03.windows10-ftp-iis 截图 10" loading="lazy"></p><h2 id="启动或关闭-windows-功能" tabindex="-1">启动或关闭 Windows 功能 <a class="header-anchor" href="#启动或关闭-windows-功能" aria-label="Permalink to &quot;启动或关闭 Windows 功能&quot;">​</a></h2><p>Win+S键搜索控制面板，打开顺序【控制面板-程序和功能-启动或关闭Windows功能】，在弹出的窗口中选择以下选项：</p><p><img src="'+g+'" alt="03.windows10-ftp-iis 截图 11" loading="lazy"></p><p>点击确认，然后重启电脑即可搜索到IIS管理器</p>',39)])])}const D=a(P,[["render",f]]);export{b as __pageData,D as default};
